INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES
('devops', 'networking', 'overview', 'What determines whether a load balancer operates ''at L4'' or ''at L7''?', '["The physical hardware brand of the load balancer", "Whether it routes based only on raw IP:port (L4, fast, blind to content) or reads the actual HTTP request to route by URL path etc. (L7, slower, more capable)", "Whether the load balancer is deployed in the cloud or on-premise", "Whether the connection uses IPv4 or IPv6"]', 1, 'L4 load balancing forwards raw TCP/UDP traffic by IP:port without inspecting content; L7 reads the actual HTTP request (path, headers) to make routing decisions -- the layer determines what information the load balancer can see and act on.', 'beginner'),
('devops', 'networking', 'overview', 'Why is UDP the right choice for DNS lookups and video streaming, per the overview''s TCP vs UDP framing?', '["Because UDP is more secure than TCP by default", "A dropped packet in these cases just means a retry or a tiny glitch, not corrupted data -- UDP skips TCP''s reliability overhead for speed, accepting that tradeoff where it''s acceptable", "Because UDP guarantees in-order delivery, which TCP does not", "Because DNS and video streaming cannot technically be implemented using TCP"]', 1, 'UDP trades reliability for speed -- acceptable exactly when a lost packet means a quick retry (DNS) or a minor visual glitch (video) rather than corrupted, unacceptable data loss, unlike a database connection where TCP''s guarantees matter.', 'beginner'),
('devops', 'networking', 'overview', 'What does DNS TTL (Time To Live) control, and what''s the tradeoff between a low and high value?', '["TTL controls how long a TLS certificate remains valid", "TTL controls how long a DNS answer is cached; a low TTL allows fast domain repointing during a migration at the cost of more DNS queries, while a high TTL means fewer queries but slower propagation when something needs to change", "TTL controls the maximum number of hops a packet can take before being dropped", "TTL only applies to UDP traffic, never to DNS specifically"]', 1, 'TTL governs DNS answer caching duration -- a low TTL trades more frequent queries for fast repointing ability (useful during migrations), while a high TTL trades slower propagation for fewer queries overall.', 'intermediate'),
('devops', 'networking', 'overview', 'What does CoreDNS provide inside a Kubernetes cluster?', '["It encrypts all pod-to-pod traffic automatically", "It gives every internal Service its own hostname so Pods can reach each other by name instead of a constantly-changing IP", "It replaces the need for an Ingress controller entirely", "It manages TLS certificate issuance and renewal for all Services"]', 1, 'CoreDNS is Kubernetes'' internal DNS implementation of the same general DNS concept -- resolving stable Service hostnames instead of requiring Pods to track constantly-changing Pod/Service IPs directly.', 'beginner'),
('devops', 'networking', 'overview', 'In Kubernetes NetworkPolicy semantics, what happens to traffic that doesn''t match any rule, once at least one NetworkPolicy selects a given pod?', '["Unmatched traffic is allowed by default, since NetworkPolicies are additive-only", "Network Policies act as a whitelist -- once any policy selects a pod, ALL unmatched traffic to that pod is blocked, not just the traffic the policy explicitly mentions", "Unmatched traffic is logged but still allowed through", "NetworkPolicies only affect egress traffic, never ingress, regardless of configuration"]', 1, 'The overview is explicit: NetworkPolicies are a whitelist model -- as soon as any policy selects a pod, all traffic that isn''t explicitly allowed by a matching rule is blocked, which is a common source of unexpected traffic blocking if not understood.', 'intermediate'),
('devops', 'networking', 'fundamentals', 'Per the fundamentals content, what is the core difference in what an L4 vs L7 load balancer can route based on?', '["L4 and L7 load balancers route identically; the distinction is purely about hardware cost", "L4 routes based on IP + port only, protocol-agnostic and fast; L7 routes based on HTTP content (path, headers, cookies) and can also do SSL termination and session stickiness", "L7 is always faster than L4 because it processes less data", "L4 can only be used for UDP traffic, never TCP"]', 1, 'L4 (Network Load Balancer example) is protocol-agnostic and fast, routing purely on IP:port; L7 (Application Load Balancer, NGINX) reads actual HTTP content to enable path-based routing, stickiness, and SSL termination -- at higher processing cost.', 'beginner'),
('devops', 'networking', 'fundamentals', 'Per the HTTP status code table, what does a 503 specifically indicate, in contrast to a 504?', '["503 and 504 mean exactly the same thing -- no healthy backend responded", "503 (Service Unavailable) means no healthy backends exist to serve the request; 504 (Gateway Timeout) means a backend exists but was too slow to respond in time", "503 means the client sent malformed data; 504 means the server rejected the request outright", "503 only applies to DNS failures; 504 only applies to TLS handshake failures"]', 1, 'The table distinguishes these precisely: 503 signals no healthy backend is available at all, while 504 signals a backend exists but didn''t respond within the timeout -- different root causes needing different diagnostics.', 'intermediate'),
('devops', 'networking', 'fundamentals', 'What does HTTP/2 multiplexing enable that HTTP/1.1 needed domain-sharding tricks to work around?', '["HTTP/2 eliminates the need for DNS resolution entirely", "HTTP/2 sends many requests over a single TCP connection simultaneously, meaningfully reducing page load time for sites with many small assets without needing HTTP/1.1''s domain-sharding workaround", "HTTP/2 removes the need for TLS encryption on any connection", "HTTP/2 only works over UDP, never over TCP"]', 1, 'HTTP/1.1 opened a new connection per request (or reused one serially), which teams worked around via domain sharding; HTTP/2''s multiplexing over one connection makes that workaround unnecessary while still reducing load time for asset-heavy sites.', 'intermediate'),
('devops', 'networking', 'fundamentals', 'What specific problem does curl''s `-w "@curl-format.txt"` timing breakdown solve?', '["It reduces the total time a curl request takes to complete", "It breaks down DNS lookup, TCP connect, TLS handshake, and time-to-first-byte separately -- essential for isolating WHERE latency actually comes from, rather than guessing", "It automatically retries a failed request up to 3 times", "It converts the HTTP response body from JSON to plain text"]', 1, 'The timing breakdown separates each phase of a request (DNS, TCP connect, TLS handshake, TTFB) so a slow request can be isolated to a specific layer instead of treating overall latency as one undifferentiated number.', 'intermediate'),
('devops', 'networking', 'fundamentals', 'Per the fundamentals interview content, when should TCP be chosen over UDP?', '["Whenever the absolute lowest latency is required, regardless of correctness needs", "When data correctness matters more than raw speed -- HTTP/HTTPS, SSH, database connections -- since TCP guarantees in-order, reliable delivery via retransmission", "Only when the application is written in a compiled language", "TCP should always be chosen over UDP in every case, since UDP is strictly obsolete"]', 1, 'The fundamentals content frames the choice around correctness vs. speed tradeoffs -- TCP''s handshake, acknowledgment, and retransmission overhead is worth it precisely when every byte and its order matter, as with database connections or SSH.', 'beginner'),
('devops', 'networking', 'intermediate', 'What do the net.ipv4.tcp_tw_reuse and net.ipv4.tcp_fin_timeout sysctl settings specifically address?', '["They configure the maximum bandwidth a single TCP connection can use", "They address TIME_WAIT socket accumulation on high-traffic servers -- reusing TIME_WAIT sockets and reducing the FIN timeout from the 60s default helps prevent connection-state buildup", "They control which network interface is used for outbound traffic", "They configure DNS resolver timeout behavior specifically"]', 1, 'These sysctl settings are specifically about managing TCP connection state under high churn -- reusing TIME_WAIT sockets and shortening the FIN timeout reduces the connection-state accumulation that can occur on busy servers.', 'advanced'),
('devops', 'networking', 'intermediate', 'What is a Linux network namespace, and what do Docker and Kubernetes use it for?', '["A DNS naming convention for internal services, unrelated to the kernel", "An isolated network stack (its own interfaces, routing table, etc.) -- Docker and Kubernetes use network namespaces internally to give each container its own isolated network environment", "A cloud-provider-specific feature only available on AWS", "A firewall rule set applied at the application layer"]', 1, 'Network namespaces provide isolated network stacks at the kernel level -- the content explicitly notes this is exactly what Docker does for each container, demonstrated by manually creating one with ip netns.', 'intermediate'),
('devops', 'networking', 'intermediate', 'In iptables, what is the difference between the PREROUTING and POSTROUTING chains?', '["They are two names for the exact same chain, kept for backward compatibility", "PREROUTING processes traffic before a routing decision is made (used for DNAT); POSTROUTING processes traffic after routing (used for SNAT/masquerade)", "PREROUTING only applies to IPv6 traffic; POSTROUTING only applies to IPv4", "POSTROUTING runs before PREROUTING in the actual packet processing order"]', 1, 'The chains are ordered around the routing decision: PREROUTING (before routing, used for destination NAT/port forwarding) and POSTROUTING (after routing, used for source NAT/masquerading outbound traffic).', 'advanced'),
('devops', 'networking', 'intermediate', 'What real problem does the IP Hash load balancing algorithm have specifically for clients sitting behind NAT?', '["IP Hash cannot technically be implemented for HTTPS traffic", "Many different real users can share one public IP behind NAT, so hash(client_ip) sends all of them to the same backend server -- causing uneven load distribution despite the algorithm working exactly as designed", "IP Hash requires significantly more CPU than round robin, making it impractical at scale", "IP Hash is incompatible with any load balancer that also performs SSL termination"]', 1, 'IP Hash provides session affinity without cookies by hashing the client IP -- but behind NAT, many distinct users share one IP, so they all hash to the same backend, causing genuine load imbalance even though the algorithm is functioning correctly.', 'advanced'),
('devops', 'networking', 'intermediate', 'In the network troubleshooting toolkit''s connectivity debug path, what is checked immediately after confirming DNS resolves and before checking TLS?', '["Whether the application''s database schema is up to date", "Whether the route is reachable and the specific port is open (traceroute/mtr, then nc -zv or telnet)", "Whether the CI/CD pipeline''s last deploy succeeded", "Whether the client''s browser cache needs to be cleared"]', 1, 'The described sequence is DNS resolving, then route reachability, then port-open verification, then TLS working, then the actual HTTP response -- an ordered path that isolates which specific layer is actually failing.', 'intermediate'),
('devops', 'networking', 'advanced', 'What does Cilium replace iptables with for Kubernetes networking, and why is this faster?', '["Cilium replaces iptables with a completely separate hardware appliance", "Cilium replaces iptables with eBPF programs running inside the Linux kernel, which is significantly faster than iptables'' traditional rule-matching approach at scale", "Cilium eliminates the need for any packet filtering at all", "Cilium replaces iptables with a userspace proxy written in Go"]', 1, 'Cilium is explicitly described as using eBPF (sandboxed kernel programs) instead of iptables -- a fundamentally different, much faster mechanism for the same packet-filtering/policy-enforcement job, used by companies like Cloudflare, Meta, and Netflix.', 'intermediate'),
('devops', 'networking', 'advanced', 'What does Hubble provide as part of the Cilium ecosystem?', '["Hubble is Cilium''s certificate management component", "Hubble is Cilium''s observability tool, letting you observe live traffic flows in the cluster (e.g. hubble observe --namespace production)", "Hubble replaces CoreDNS as the cluster''s DNS resolver", "Hubble is a load testing tool bundled with Cilium"]', 1, 'Hubble is specifically named as Cilium''s observability layer, used to observe live network flows (per-namespace or per-pod) -- distinct from Cilium''s core eBPF-based policy enforcement.', 'intermediate'),
('devops', 'networking', 'advanced', 'What does MetalLB''s BGP mode provide for bare-metal Kubernetes clusters?', '["It provides free TLS certificates for all Services automatically", "It lets a bare-metal cluster provide LoadBalancer-type Services by peering with a physical router via BGP, advertising IP address pool routes -- a capability normally provided by a cloud provider''s managed load balancer", "It replaces the need for kube-proxy entirely", "It is only usable for DNS record management, not load balancing"]', 1, 'MetalLB''s BGP mode fills a gap for bare-metal clusters that don''t have a cloud provider''s LoadBalancer integration -- peering with a router via BGP to advertise routes for a configured IP address pool.', 'advanced'),
('devops', 'networking', 'advanced', 'How does Calico''s BGP mode differ from an overlay network (like VXLAN) for pod-to-pod traffic?', '["Calico''s BGP mode requires every pod to have a public internet-routable IP", "Calico''s BGP mode advertises pod CIDRs directly to physical routers, making pods directly routable in the data center without an overlay -- avoiding the encapsulation overhead an overlay network requires", "BGP mode is purely a monitoring feature and has no effect on actual packet routing", "Overlay networks are always faster than BGP mode regardless of network topology"]', 1, 'BGP mode advertises pod CIDRs to the physical network directly, making pods routable without VXLAN-style encapsulation -- a genuinely different approach from overlay networking, trading some setup complexity for avoiding encapsulation overhead.', 'advanced'),
('devops', 'networking', 'advanced', 'What do increasing net.core.rmem_max and net.core.wmem_max sysctl values address in network performance tuning?', '["They increase the maximum number of concurrent TCP connections allowed", "They increase the kernel''s receive and send buffer size ceilings, which matters for high-throughput servers where default buffer sizes become a bottleneck", "They control how long a DNS record is cached in the kernel", "They disable TCP''s congestion control algorithm entirely"]', 1, 'These settings raise the maximum receive/send buffer sizes (e.g. to 128MB) -- relevant tuning for high-throughput servers where the default, smaller buffer ceilings would otherwise limit achievable throughput.', 'advanced'),
('devops', 'istio', 'overview', 'What is mTLS (mutual TLS), and how does it differ from regular TLS?', '["mTLS is simply TLS with a longer certificate expiry period", "In mTLS, both sides of a connection authenticate each other; in regular TLS, only the server proves its identity to the client", "mTLS only works for UDP traffic, while regular TLS only works for TCP", "mTLS eliminates the need for any certificate authority"]', 1, 'The overview is precise: mTLS is mutual (both client and server authenticate each other), unlike regular TLS where only the server side proves its identity -- Istio provides this automatically via sidecar-issued SPIFFE certificates.', 'beginner'),
('devops', 'istio', 'overview', 'Per the airport-customs analogy, what problem does the Envoy sidecar proxy model solve?', '["It eliminates the need for any network traffic between microservices", "Instead of every microservice individually implementing its own mTLS, retries, and auth (every room checking IDs itself), a sidecar proxy at every doorway checks and enforces policy automatically -- zero application code changes required", "It replaces Kubernetes'' own Service object entirely", "It only works for HTTP traffic, not gRPC or TCP"]', 1, 'The analogy maps the sidecar model directly: instead of every service (''room'') implementing mTLS/retries/auth itself, a proxy at every ''doorway'' (Envoy) enforces it uniformly and automatically, with application code unaware it''s happening.', 'beginner'),
('devops', 'istio', 'overview', 'What is the difference between STRICT and PERMISSIVE mTLS mode in Istio?', '["STRICT and PERMISSIVE are identical; the names are cosmetic only", "STRICT rejects any non-mTLS traffic outright; PERMISSIVE (the default while migrating) accepts both plaintext and mTLS traffic so existing non-mesh services don''t break during rollout", "PERMISSIVE mode disables encryption entirely, while STRICT enables it", "STRICT mode only applies to ingress traffic, never to service-to-service traffic"]', 1, 'STRICT enforces mTLS-only traffic (rejecting plaintext); PERMISSIVE accepts both, specifically to avoid breaking services not yet part of the mesh during a gradual migration -- the safer default while rolling Istio out.', 'intermediate'),
('devops', 'istio', 'overview', 'What does a DestinationRule''s outlierDetection configuration control?', '["It controls which namespaces are allowed to communicate with each other", "Circuit breaking -- if a backend pod returns a configured number of consecutive 5xx errors within a time window, Istio ejects it from the load-balancing pool for a set duration so it can recover before being re-admitted", "It controls how long mTLS certificates remain valid before rotation", "It determines which VirtualService takes priority when multiple exist"]', 1, 'outlierDetection is Istio''s circuit-breaker mechanism -- ejecting an unhealthy backend from the pool after consecutive errors, without requiring any application-level circuit-breaker code.', 'intermediate'),
('devops', 'istio', 'overview', 'Per the overview, at roughly what point does adopting Istio become worthwhile versus unnecessary operational complexity?', '["Istio should always be adopted from day one, regardless of service count", "Once there are enough microservices (typically 5+) with real cross-cutting needs (mTLS, retries, tracing) that reimplementing them per-service becomes unmaintainable", "Istio is only ever appropriate for single-service, monolithic architectures", "The decision is based entirely on team size, never on the number of services"]', 1, 'The content frames this as a genuine architectural tradeoff -- Istio earns its operational complexity once cross-cutting concerns across enough services (5+) become unmaintainable to reimplement individually, not as a default for every cluster.', 'intermediate'),
('devops', 'istio', 'fundamentals', 'Per the control-office/guard analogy, what is istiod''s role versus the Envoy sidecar''s role?', '["istiod intercepts live traffic directly; Envoy only stores configuration", "istiod computes and distributes policy/config (the ''policy office''); Envoy sidecars are the ones actually intercepting and enforcing that policy on live traffic in real time (the ''guard at the door'')", "istiod and Envoy perform the exact same function redundantly for fault tolerance", "istiod only runs during cluster startup and has no ongoing role afterward"]', 1, 'The analogy is explicit: istiod is the control plane deciding policy and pushing it out; Envoy sidecars are the data plane, enforcing that policy locally on every request without round-tripping back to istiod for each one.', 'beginner'),
('devops', 'istio', 'fundamentals', 'What does the SYNCED vs STALE distinction in `istioctl proxy-status` output indicate?', '["SYNCED means the pod has more CPU available than STALE pods", "It shows whether a specific Envoy sidecar has actually received and applied istiod''s latest pushed config (SYNCED) or is lagging behind (STALE) -- the first thing to check when a policy change doesn''t seem to take effect on one particular pod", "STALE means the pod needs to be manually restarted before Istio will work at all", "SYNCED only applies to the control plane itself, never to individual sidecars"]', 1, 'This distinction is exactly the control-plane/data-plane gap made visible: the office issuing new instructions vs. a specific guard having actually received and applied them -- the first diagnostic step when a new policy isn''t taking effect somewhere.', 'advanced'),
('devops', 'istio', 'fundamentals', 'Within istiod, what does Citadel specifically do?', '["Citadel converts Istio config into Envoy''s native xDS format", "Citadel is the Certificate Authority component -- it issues and rotates mTLS certificates (SPIFFE identities) for every service in the mesh", "Citadel validates Istio config for syntax errors before it''s applied", "Citadel manages Kubernetes'' own etcd datastore"]', 1, 'Citadel is specifically the CA sub-component inside istiod, responsible for issuing and rotating the mTLS certificates that give every service its SPIFFE identity -- distinct from Pilot (config conversion) and Galley (validation).', 'intermediate'),
('devops', 'istio', 'fundamentals', 'In the VirtualService example with a match on the x-canary-user header, what happens to requests carrying that header?', '["They are rejected outright as invalid requests", "They are routed directly to the v2 subset, bypassing the normal 90/10 weighted split applied to all other traffic", "They are duplicated and sent to both v1 and v2 simultaneously", "They trigger an automatic rollback of the canary deployment"]', 1, 'The header-matched rule takes priority over the weighted route -- requests with x-canary-user: true go straight to v2, letting specific beta users opt into the canary version regardless of the general 90/10 traffic split.', 'intermediate'),
('devops', 'istio', 'fundamentals', 'What are the three observability signals Istio automatically provides with zero application instrumentation?', '["CPU usage, memory usage, and disk I/O", "Metrics (request rate, error rate, latency per service pair), traces (distributed tracing via automatic header propagation), and logs (access logs from every Envoy sidecar)", "Git commit history, deployment frequency, and code coverage", "Database query performance, cache hit rate, and connection pool size"]', 1, 'Istio provides all three observability pillars automatically once installed and namespaces are labeled -- metrics to Prometheus/Grafana, traces to Jaeger/Zipkin, and access logs from every sidecar -- with zero application-level instrumentation required.', 'beginner'),
('devops', 'kafka', 'overview', 'What is a Kafka partition, and why is it described as ''the unit of parallelism''?', '["A partition is a separate physical Kafka cluster entirely", "A partition is a division of a topic into an ordered, immutable log; because each partition can be read independently, it''s what determines how much a topic''s reading can actually be parallelized", "A partition is a temporary cache that gets cleared every hour", "A partition only exists for topics that use the RabbitMQ protocol"]', 1, 'A topic is divided into partitions, each an independently-readable ordered log -- this is specifically why partition count determines the maximum degree of parallel consumption a topic supports.', 'beginner'),
('devops', 'kafka', 'overview', 'What is the rule relating the number of consumer instances in a consumer group to a topic''s partition count?', '["There is no relationship -- any number of consumers can always be added freely", "Consumer instances should be \u2264 partition count -- each partition is assigned to exactly one consumer within the group at a time, so extra consumers beyond the partition count sit idle with nothing assigned to them", "Partition count must always equal exactly 2x the number of consumer instances", "Consumer count must always exceed partition count for the group to function"]', 1, 'Since each partition maps to exactly one consumer within a group at a time, having more consumer instances than partitions leaves the extras with no partition assigned -- genuinely idle, not helping throughput.', 'intermediate'),
('devops', 'kafka', 'overview', 'What does lag growing on ALL partitions of a consumer group indicate, versus lag stuck on just ONE partition?', '["Both situations always indicate the exact same root cause and fix", "Lag growing on all partitions means the consumer group overall is too slow (fix: scale up consumers, up to partition count); lag stuck on one specific partition usually means a stuck consumer or a poison pill message blocking that partition specifically", "Lag on all partitions means a broker is down; lag on one partition means the network is down", "Growing lag on all partitions can only be fixed by deleting and recreating the topic"]', 1, 'The overview draws this exact diagnostic split: an across-the-board slowdown points to overall consumer throughput (add consumers), while a single stuck partition points to a specific bad message or hung consumer needing targeted investigation.', 'intermediate'),
('devops', 'kafka', 'overview', 'What is a ''poison pill message'' in Kafka?', '["A message containing a security exploit that compromises the broker", "A malformed message the consumer keeps failing to process and retrying forever, blocking everything else queued behind it on that specific partition", "A message that automatically triggers a full topic deletion", "A message type reserved exclusively for administrative commands"]', 1, 'A poison pill is a specific malformed message a consumer can never successfully process -- since it keeps retrying and failing, it blocks all subsequent messages on that partition, which is why it causes lag stuck on one partition specifically.', 'advanced'),
('devops', 'kafka', 'overview', 'Per the Kafka vs RabbitMQ decision matrix, when should Kafka specifically NOT be used?', '["Kafka should never be used for any event-streaming workload", "For a simple job queue (process a job once, then delete it) -- RabbitMQ or SQS is simpler and more operationally appropriate there, since Kafka''s replay/retention/throughput strengths aren''t the actual requirement", "Kafka should never be used with Kubernetes, only with bare-metal servers", "Kafka cannot technically be used for any use case involving fewer than 3 brokers"]', 1, 'The content is explicit that Kafka is over-engineering for a simple task queue -- RabbitMQ/SQS''s push-based, delete-after-consume model is a better operational fit when replay, fan-out, and extreme throughput aren''t actually needed.', 'intermediate'),
('devops', 'kafka', 'fundamentals', 'Why can a new consumer group, added months after a topic was created, still read the topic''s entire history from the beginning?', '["Kafka automatically re-sends every historical message to any newly created consumer group", "A Kafka message stays in the log after being read (unlike a task queue where it''s deleted on consumption) -- retention keeps it available for days/weeks, so a new consumer group can start from the earliest offset and read the full history", "New consumer groups are given administrative access to the broker''s raw disk storage", "Kafka topics have unlimited retention by default with no configuration needed"]', 1, 'Kafka''s fundamental difference from a task queue is that reading doesn''t delete a message -- it persists per the retention policy, so any consumer group (new or old) can independently replay from the earliest available offset.', 'beginner'),
('devops', 'kafka', 'fundamentals', 'Why is message ordering in Kafka only guaranteed within a single partition, never across partitions?', '["Ordering across partitions is guaranteed too, contrary to common belief", "Messages are distributed across partitions (often by key), and each partition is an independent log processed by potentially different consumers -- there''s no single, globally-ordered sequence spanning multiple independently-processed logs", "Kafka does not guarantee ordering at all, even within a single partition", "Ordering across partitions is only broken when replication factor exceeds 1"]', 1, 'Since partitions are independent logs (often read in parallel by different consumers), there''s no mechanism enforcing a single total order across them -- ordering is a per-partition guarantee, which is why same-key messages are routed to the same partition when order matters.', 'intermediate'),
('devops', 'kafka', 'fundamentals', 'What breaks if a topic''s partition count is increased after keyed data has already been produced?', '["Nothing breaks -- partition count can always be changed freely with zero side effects", "The key-to-partition hash mapping changes with a different partition count, so previously-produced keyed messages no longer map to the same partition a new message with the same key would land on -- breaking the guarantee that same-key messages stay together", "Increasing partition count automatically deletes all previously stored messages", "Consumer groups automatically re-balance instantly with zero downtime, so nothing is affected"]', 1, 'The hash-to-partition assignment is a function of partition count -- changing that count changes where a given key would now land, breaking the previously-established key-to-partition consistency for already-produced data.', 'advanced'),
('devops', 'kafka', 'fundamentals', 'What does KEDA''s kafka trigger scale consumer pods based on?', '["The total disk space used by the Kafka cluster", "Consumer group lag -- scaling up when lag exceeds a configured threshold (e.g. lagThreshold: \"50\")", "The number of topics currently registered in the cluster", "The CPU utilization of the Kafka brokers themselves"]', 1, 'KEDA''s Kafka scaler specifically watches consumer group lag against a configured threshold, scaling consumer pods up when lag grows past it -- a queue-depth-style signal, not a CPU/memory-based one.', 'intermediate'),
('devops', 'kafka', 'fundamentals', 'What does Confluent Schema Registry specifically prevent that plain Apache Kafka doesn''t protect against?', '["It prevents brokers from going offline unexpectedly", "In plain Kafka, producers and consumers agree on message format only by convention -- if a producer changes the schema, consumers break silently; Schema Registry enforces a contract, rejecting breaking schema changes at produce time before they ever reach a consumer", "It prevents consumer lag from ever growing under any load", "It automatically encrypts all messages at rest without any configuration"]', 1, 'Without Schema Registry, a schema change (like a renamed field) can silently break every downstream consumer with no warning; Schema Registry enforces schema evolution rules, rejecting a breaking change at produce time instead of letting it fail silently downstream.', 'intermediate')
